import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Resource and Dependency Model","description":"","frontmatter":{"title":"Resource and Dependency Model"},"headers":[],"relativePath":"guide/resources.md","filePath":"guide/resources.md","lastUpdated":1793266312000}`),a={name:`guide/resources.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_3-resource-and-dependency-model" tabindex="-1">3. Resource and Dependency Model <a class="header-anchor" href="#_3-resource-and-dependency-model" aria-label="Permalink to “3. Resource and Dependency Model”">​</a></h1><h2 id="_3-1-resource-definition" tabindex="-1">3.1 Resource definition <a class="header-anchor" href="#_3-1-resource-definition" aria-label="Permalink to “3.1 Resource definition”">​</a></h2><p>A Resource is the basic object that Custos monitors and recovers.</p><p>Example resource types:</p><ul><li><code>process</code></li><li><code>system-service</code></li><li><code>network-interface</code></li><li><code>network-connectivity</code></li><li><code>proxy</code></li><li><code>tunnel</code></li><li><code>http-endpoint</code></li><li><code>custom-command</code></li><li><code>database</code></li><li><code>application</code></li></ul><p>Every resource should have:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Resource</span></span>
<span class="line"><span>├── id</span></span>
<span class="line"><span>├── type</span></span>
<span class="line"><span>├── display_name</span></span>
<span class="line"><span>├── plugin_ref</span></span>
<span class="line"><span>├── config</span></span>
<span class="line"><span>├── health_policy</span></span>
<span class="line"><span>├── recovery_policy</span></span>
<span class="line"><span>├── dependencies[]</span></span>
<span class="line"><span>├── permissions</span></span>
<span class="line"><span>└── enabled</span></span></code></pre></div><p>Field semantics:</p><ul><li><code>id</code>: a stable, unique identifier within configuration scope.</li><li><code>type</code>: the resource type.</li><li><code>plugin_ref</code>: the plugin implementing the resource capabilities.</li><li><code>config</code>: configuration specific to the resource type.</li><li><code>health_policy</code>: health criteria, consecutive failure thresholds and recovery confirmation requirements.</li><li><code>recovery_policy</code>: recovery candidate plans and recovery limits.</li><li><code>dependencies</code>: the resource&#39;s upstream dependencies.</li><li><code>permissions</code>: the scope of operations allowed for this resource.</li><li><code>enabled</code>: whether monitoring and automatic recovery are enabled.</li></ul><p>Resource IDs must not change across process restarts, plugin restarts or machine reboots.</p><h2 id="_3-2-resource-health-status" tabindex="-1">3.2 Resource health status <a class="header-anchor" href="#_3-2-resource-health-status" aria-label="Permalink to “3.2 Resource health status”">​</a></h2><p>The following health states are recommended:</p><div class="language-rust" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">enum</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HealthStatus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Unknown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Healthy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Degraded</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Unhealthy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Recovering</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Suppressed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Unreachable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>State semantics:</p><ul><li><code>Unknown</code>: not enough evidence has been collected yet.</li><li><code>Healthy</code>: health criteria are satisfied.</li><li><code>Degraded</code>: some capability is impaired, but the service still works.</li><li><code>Unhealthy</code>: health criteria are clearly not satisfied.</li><li><code>Recovering</code>: a recovery process is being executed.</li><li><code>Suppressed</code>: automatic handling is paused by policy.</li><li><code>Unreachable</code>: the probe itself cannot obtain a valid result, so the root cause cannot yet be confirmed.</li></ul><p><code>Unreachable</code> must not be treated as equivalent to <code>Unhealthy</code>. For example, a probe timeout against a remote service could mean the remote end failed, or that the local network failed.</p><p>Resource state should also record:</p><ul><li>When the state was last updated.</li><li>Consecutive success and failure counts.</li><li>The time of the last valid probe.</li><li>The currently active fault identifier.</li><li>The RecoveryRun currently being executed.</li><li>A summary of the current evidence.</li></ul><h2 id="_3-3-dependency-definition" tabindex="-1">3.3 Dependency definition <a class="header-anchor" href="#_3-3-dependency-definition" aria-label="Permalink to “3.3 Dependency definition”">​</a></h2><p>A dependency describes the conditions a resource needs satisfied in order to run normally.</p><p>Suggested definition:</p><div class="language-rust" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    target_resource_id</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ResourceId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    requirement</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DependencyRequirement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    condition</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HealthCondition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    resolution_policy</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DependencyResolutionPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    timeout</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Duration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>where:</p><div class="language-rust" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">enum</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DependencyRequirement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Required</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Optional</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Conditional</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    AlternativeGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Concrete semantics:</p><h3 id="required" tabindex="-1">Required <a class="header-anchor" href="#required" aria-label="Permalink to “Required”">​</a></h3><p>A dependency that must be satisfied.</p><p>If it is not, recovery actions that depend on it cannot be executed — unless the action is explicitly marked as being for recovering that dependency itself.</p><h3 id="optional" tabindex="-1">Optional <a class="header-anchor" href="#optional" aria-label="Permalink to “Optional”">​</a></h3><p>A non-mandatory dependency.</p><p>Recovery may be attempted, but whether it blocks upstream operations is decided by policy.</p><h3 id="conditional" tabindex="-1">Conditional <a class="header-anchor" href="#conditional" aria-label="Permalink to “Conditional”">​</a></h3><p>Only required under specific conditions.</p><p>For example, the proxy must be healthy in proxy mode, but not in direct-connection mode.</p><h3 id="alternativegroup" tabindex="-1">AlternativeGroup <a class="header-anchor" href="#alternativegroup" aria-label="Permalink to “AlternativeGroup”">​</a></h3><p>A set of candidate resources where the specified number must be satisfied.</p><p>For example:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProxyAccess</span></span>
<span class="line"><span>├── PrimaryProxy</span></span>
<span class="line"><span>└── BackupProxy</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requirement: at least one available</span></span></code></pre></div><p>Backup resources must not be naively modeled as &quot;every dependency must be healthy&quot;.</p><h2 id="_3-4-health-conditions" tabindex="-1">3.4 Health conditions <a class="header-anchor" href="#_3-4-health-conditions" aria-label="Permalink to “3.4 Health conditions”">​</a></h2><p>A dependency must declare which health condition it depends on, not merely which resource it depends on.</p><p>Example:</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">resource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">proxy.egress</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    requirement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">required</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">      status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">healthy</span></span></code></pre></div><p>More complex conditions may require:</p><ul><li>The resource status to be Healthy.</li><li>A specific capability to be available.</li><li>The last successful probe to be no older than a specified time.</li><li>Consecutive successes to reach a specified count.</li><li>A specific business check to pass.</li></ul><p>The first version should implement only a small set of clear, testable conditions — no arbitrary expression language.</p><h2 id="_3-5-dependency-graph-and-cycle-detection" tabindex="-1">3.5 Dependency graph and cycle detection <a class="header-anchor" href="#_3-5-dependency-graph-and-cycle-detection" aria-label="Permalink to “3.5 Dependency graph and cycle detection”">​</a></h2><p>Dependencies form a directed graph.</p><p>If resource A depends on B, the dependency edge is:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A -&gt; B</span></span></code></pre></div><p>When recovering A, B is evaluated first.</p><p>At configuration load time, Custos must:</p><ol><li>Verify resource IDs are unique.</li><li>Verify all dependency references exist.</li><li>Detect hard dependency cycles.</li><li>Verify that AlternativeGroup configurations are valid.</li><li>Check for dependency conditions that can never be satisfied.</li><li>Report the exact configuration error path.</li></ol><p>For:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A -&gt; B -&gt; C -&gt; A</span></span></code></pre></div><p>startup must be rejected at configuration time; the system must not wait until recovery and recurse forever.</p><p>The first version may forbid all ordinary dependency cycles. If cycles or mutual-backup relationships are ever needed later, they should be modeled through explicit redundancy constructs, not by allowing arbitrary cycles.</p><h2 id="_3-6-dependency-recovery-algorithm" tabindex="-1">3.6 Dependency recovery algorithm <a class="header-anchor" href="#_3-6-dependency-recovery-algorithm" aria-label="Permalink to “3.6 Dependency recovery algorithm”">​</a></h2><p>When recovering resource A:</p><ol><li>Collect A&#39;s dependency set.</li><li>Check whether each dependency&#39;s current state is fresh enough.</li><li>Re-probe when state is unknown or stale.</li><li>Dependencies whose conditions are satisfied pass directly.</li><li>Unsatisfied dependencies enter recovery according to their own policy.</li><li>Wait for dependency recovery to complete.</li><li>Re-verify dependency health.</li><li>Only after all required dependencies are satisfied may A&#39;s recovery actions execute.</li><li>If dependency recovery fails, A&#39;s policy decides whether to wait, skip non-critical dependencies, terminate or escalate.</li></ol><p>Two kinds of actions must be distinguished:</p><ul><li>Recovery actions executed in order to fix the dependency itself.</li><li>Upstream actions that must wait for the dependency to be healthy before executing.</li></ul><p>For example, when the proxy is unhealthy, &quot;switch proxy node&quot; is allowed; but restarting the Cloudflare Tunnel — which depends on the proxy — should not be executed while expecting it to succeed.</p><h2 id="_3-7-concurrency-and-dependency-deduplication" tabindex="-1">3.7 Concurrency and dependency deduplication <a class="header-anchor" href="#_3-7-concurrency-and-dependency-deduplication" aria-label="Permalink to “3.7 Concurrency and dependency deduplication”">​</a></h2><p>The same resource may be depended on by multiple upstream resources.</p><p>For example:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Cloudflare Tunnel ──&gt; Proxy</span></span>
<span class="line"><span>Sunlogin ────────────&gt; Network</span></span>
<span class="line"><span>Other Service ───────&gt; Proxy</span></span></code></pre></div><p>If multiple recovery tasks discover at the same time that the Proxy is unhealthy, multiple proxy restart tasks must not be started simultaneously.</p><p>Requirements:</p><ul><li>Each resource has its own recovery mutex.</li><li>At most one active RecoveryRun per resource at a time.</li><li>Other tasks may wait on the same recovery result.</li><li>When resource health changes, waiting tasks re-evaluate their dependencies.</li><li>Recovery tasks must not repeatedly start the same high-risk action.</li><li>Global and per-resource recovery budgets must be defined.</li></ul><hr>`,71)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};